799	function pipeStdin(
800	  cmd: string,
801	  args: string[],
802	  stdin: string,
803	  timeoutMs: number,
804	): Promise<{ code: number | null; signal: NodeJS.Signals | null; stdout: string; stderr: string }> {
805	  return new Promise((resolveP, rejectP) => {
806	    const proc = spawn(cmd, args, { timeout: timeoutMs });
807	    let stdout = '';
808	    let stderr = '';
809	    proc.stdout.on('data', (c: Buffer) => {
810	      stdout += c.toString();
811	    });
812	    proc.stderr.on('data', (c: Buffer) => {
813	      stderr += c.toString();
814	    });
815	    // rtk may exit before reading stdin; EPIPE must not become unhandled.
816	    proc.stdin.on('error', (err: NodeJS.ErrnoException) => {
817	      if (err.code !== 'EPIPE') {
818	        console.warn('[RtkService.pipeStdin] unexpected stdin error:', err);
819	      }
820	    });
821	    proc.on('error', rejectP);
822	    proc.on('close', (code, signal) => resolveP({ code, signal, stdout, stderr }));
823	    proc.stdin.write(stdin);
824	    proc.stdin.end();
825	  });
826	}
