947	function assertSafeArchiveMember(entry: TarEntry, destDir: string): void {
948	  // Refuse symlinks/hardlinks outright. `tar -xzf` honors their targets at
949	  // extract time, so a crafted archive with `rtk -> /etc/passwd` would let
950	  // chmod/exec follow the link out of dest even though the entry name is
951	  // benign. Defense-in-depth: SHA-256 + URL allowlist already make this hard
952	  // to reach, but the link types themselves are never legitimate in an rtk
953	  // release tarball.
954	  if (entry.type === 'symlink' || entry.type === 'hardlink') {
955	    throw new Error(`Archive contains ${entry.type}, which is not allowed: ${entry.name}`);
956	  }
957	  if (entry.type === 'other') {
958	    throw new Error(`Archive contains unsupported member type: ${entry.name}`);
959	  }
960	  // Reject embedded null bytes — tar entries should never contain them, and
961	  // some libcs truncate at \0 which could let a malicious entry name slip
962	  // past a downstream check.
963	  if (entry.name.includes('\0')) {
964	    throw new Error(`Archive member contains null byte: ${JSON.stringify(entry.name)}`);
965	  }
966	  // Reject absolute paths. The Windows-drive regex runs on every platform by
967	  // design: a tarball authored on Windows can reach any OS, so we refuse
968	  // `C:\...` entries regardless of where extraction happens.
969	  if (entry.name.startsWith('/') || /^[a-zA-Z]:[\\/]/.test(entry.name)) {
970	    throw new Error(`Archive contains absolute path: ${entry.name}`);
971	  }
972	  // Normalize backslashes to forward slashes before resolve(). On POSIX,
973	  // path.resolve treats `\` as a literal filename character, so `..\\evil`
974	  // would not be recognised as a parent-traversal attempt without this step.
975	  const normalized = normalize(entry.name.replace(/\\/g, '/'));
976	  const resolved = resolve(destDir, normalized);
977	  const base = resolve(destDir) + sep;
978	  if (resolved !== resolve(destDir) && !resolved.startsWith(base)) {
979	    throw new Error(`Archive member escapes destDir: ${entry.name}`);
980	  }
981	}
