83	/**
84	 * Atomic write: stage to a sibling tmp file then rename over the target.
85	 * POSIX rename is atomic, so a crash mid-write can never leave a half-
86	 * written file at `target`. Important here because settings.local.json is
87	 * rewritten frequently (every PTY spawn, every commit-attribution change)
88	 * and the corrupt-recovery path on the read side would otherwise have to
89	 * handle a wider class of partial-write failures than just user edits.
90	 *
91	 * On failure (write error mid-data, or rename error after a successful
92	 * write), unlink the tmp file best-effort before rethrowing so failed
93	 * writes don't accumulate orphan `*.tmp-<pid>-<ts>` files alongside the
94	 * user's settings.
95	 */
96	function atomicWriteFileSync(target: string, data: string): void {
97	  const tmp = `${target}.tmp-${process.pid}-${Date.now()}`;
98	  try {
99	    fs.writeFileSync(tmp, data);
100	    fs.renameSync(tmp, target);
101	  } catch (err) {
102	    try {
103	      fs.unlinkSync(tmp);
104	    } catch {
105	      // best-effort: tmp may not exist if writeFileSync failed before
106	      // creating the file, or unlink may race with another process.
107	    }
108	    throw err;
109	  }
110	}
