122	/**
123	 * Write .claude/settings.local.json with hooks for activity monitoring,
124	 * tool tracking, error detection, and context usage.
125	 *
126	 * Hooks use type: "http" — Claude Code POSTs the hook JSON body directly
127	 * to our local HookServer. The statusLine uses type: "command" with curl
128	 * (http type is not supported for statusLine).
129	 *
130	 * Merging preserves user-authored entries via the merge module's brand-or-
131	 * URL-shape detector, so users can have their own hooks under managed
132	 * events without losing them on every rewrite.
133	 *
134	 * Returns a result so refreshActivePtyHooks can aggregate failures across
135	 * tasks; toasts and console.error are still emitted inline regardless.
136	 */
137	export function writeHookSettings(cwd: string, ptyId: string): HookWriteResult {
138	  const port = hookServer.port;
139	  const claudeDir = path.join(cwd, '.claude');
140	  const settingsPath = path.join(claudeDir, 'settings.local.json');
141	
142	  // The await order in main.ts (`await hookServer.start()` before IPC
143	  // registration) makes this branch unreachable in normal startup; if we hit
144	  // it, something has invoked writeHookSettings outside the IPC entry path.
145	  // Surface it loudly rather than leaving stale on-disk hooks unchanged.
146	  if (port === 0) {
147	    console.error(
148	      '[writeHookSettings] HookServer port not bound — settings.local.json not updated. ' +
149	        `Likely a startup-ordering bug (caller invoked before hookServer.start() resolved). cwd=${cwd}`,
150	    );
151	    broadcastToast(
152	      `Hook server not ready — task hooks couldn't be written for ${path.basename(cwd)}. Restart Dash to recover.`,
153	    );
154	    return { ok: false, settingsPath, error: 'HookServer port not bound' };
155	  }
156	
157	  // Hooks post to the HookServer via a guarded curl command, NOT a baked
158	  // `type: "http"` URL. Two reasons, both about the URL no longer hard-coding
159	  // the port:
160	  //   1. The port is read at runtime from $DASH_HOOK_PORT, which ptyManager
161	  //      injects into the env of the Claude process Dash spawns. A session NOT
162	  //      launched by Dash (the user opening the same worktree in a plain
163	  //      `claude`) has no such var, so the `[ -n … ] || exit 0` guard makes
164	  //      every hook a silent no-op instead of an ECONNREFUSED error.
165	  //   2. Even inside Dash, the HookServer binds a fresh ephemeral port each
166	  //      launch — reading it live means a stale settings.local.json from a
167	  //      prior session self-heals instead of firing at a dead port.
168	  // The hook payload arrives on the command's stdin; `-d @-` forwards it as the
169	  // POST body, matching what the old http hook sent.
170	  //
171	  // POSIX-sh only, by design. Claude Code runs command hooks via `sh -c` on
172	  // macOS/Linux (so this is safe even for fish/zsh users) and via Git Bash or
173	  // PowerShell on Windows. Dash ships macOS arm64 + Linux x64 only, so this
174	  // syntax targets `sh` and is NOT given a win32 branch — unlike the
175	  // context-injection hook below, whose base64 decode genuinely differs by OS.
176	  // The `$DASH_HOOK_PORT` guard, not Windows support, is the reason it's a
177	  // command rather than the old `type:"http"` hook.
178	  const hookCommand = (endpoint: DashHookEndpoint): string => {
179	    const url = `http://127.0.0.1:$DASH_HOOK_PORT/hook/${endpoint}?ptyId=${ptyId}`;
180	    return (
181	      `[ -n "$DASH_HOOK_PORT" ] || exit 0; ` +
182	      `curl -s --max-time 2 -X POST -H 'Content-Type: application/json' -d @- "${url}" >/dev/null 2>&1`
183	    );
184	  };
185	
186	  const commandHook = (endpoint: DashHookEndpoint, async?: boolean): CommandHook => ({
187	    type: 'command' as const,
188	    command: hookCommand(endpoint),
189	    ...(async ? { async: true } : {}),
190	  });
191	
192	  const dashCmd = (endpoint: DashHookEndpoint, async?: boolean) =>
193	    tagDash(commandHook(endpoint, async));
194	
195	  // Typed against DashHookEvent so a typo'd event key (e.g. 'PreToolUze')
196	  // fails the build, matching the drift-prevention DashHookEndpoint gives
197	  // us for endpoints.
198	  const dashEntries: Partial<Record<DashHookEvent, HookEntry[]>> = {
199	    Stop: [{ matcher: '', hooks: [dashCmd('stop')] }],
200	    UserPromptSubmit: [{ matcher: '', hooks: [dashCmd('busy')] }],
201	    Notification: [
202	      { matcher: 'permission_prompt', hooks: [dashCmd('notification')] },
203	      { matcher: 'idle_prompt', hooks: [dashCmd('notification')] },
204	    ],
205	    PreToolUse: buildPreToolUseHooks(dashCmd),
206	    PostToolUse: [{ matcher: '*', hooks: [dashCmd('tool-end', true)] }],
207	    PreCompact: [{ matcher: '*', hooks: [dashCmd('compact-start', true)] }],
208	    SessionEnd: [{ matcher: '*', hooks: [dashCmd('session-end', true)] }],
209	  };
210	
211	  // PostCompact added in Claude Code 2.1.76; older CLIs reject the key and
212	  // skip the entire settings file (GH #127), losing all Dash hooks.
213	  if (isClaudeVersionAtLeast(2, 1, 76)) {
214	    dashEntries.PostCompact = [{ matcher: '*', hooks: [dashCmd('compact-end', true)] }];
215	  }
216	
217	  // StopFailure added in Claude Code 2.1.78.
218	  if (isClaudeVersionAtLeast(2, 1, 78)) {
219	    dashEntries.StopFailure = [{ matcher: '*', hooks: [dashCmd('stop-failure')] }];
220	  }
221	
222	  // SessionStart(clear|compact) → defensive idle. /clear and auto-compact
223	  // reset the session, so any prior busy state on the activity dot is stale.
224	  // SessionStart(resume) is NOT wired — register() already initialises and a
225	  // resumed session's busy state will be re-established by the next
226	  // UserPromptSubmit / PreToolUse hook. SessionStart(startup) was previously
227	  // wired to /hook/agent-startup for the ports onboarding TUI's auto-detect
228	  // path; we dropped that — see PortsSetupWizard (the agent self-starts via the
229	  // inlined initial prompt instead).
230	  const sessionStartEntries: HookEntry[] = [
231	    { matcher: 'clear', hooks: [dashCmd('session-start', true)] },
232	    { matcher: 'compact', hooks: [dashCmd('session-start', true)] },
233	  ];
234	
235	  // SessionStart context-injection: re-inject the task context (context prompt +
236	  // linked issue/work-item prompt) on compact and clear — which drop it from
237	  // history — but NOT startup or resume. Startup is covered by the initial-prompt
238	  // auto-submit (see setInitialPrompt / createTask): the first spawn submits the
239	  // same context as a real message the agent acts on, so a startup matcher here
240	  // would inject it a second time as silent context. Resume already has it in
241	  // history. Coexists with the defensive-idle HTTP hooks on the same matchers.
242	  const contextPrompt = getTaskContextPrompt(ptyId);
243	  if (contextPrompt) {
244	    const hookPayload = JSON.stringify({
245	      hookSpecificOutput: {
246	        hookEventName: 'SessionStart',
247	        additionalContext: contextPrompt,
248	      },
249	    });
250	    // Use base64 encoding to safely embed user-controlled content in a shell command.
251	    // Single-quote escaping is fragile with content from GitHub issues / ADO work items.
252	    const b64 = Buffer.from(hookPayload).toString('base64');
253	    // Cross-platform decode: macOS uses `base64 -D`, Linux uses `base64 -d`,
254	    // Windows cmd.exe doesn't have base64 so we use PowerShell instead.
255	    const decodeCmd =
256	      process.platform === 'win32'
257	        ? `powershell.exe -NoProfile -Command "[Console]::Out.Write([System.Text.Encoding]::UTF8.GetString([Convert]::FromBase64String('${b64}')))"`
258	        : `echo '${b64}' | base64 ${process.platform === 'darwin' ? '-D' : '-d'}`;
259	    const contextHook: CommandHook = { type: 'command', command: decodeCmd };
260	    for (const entry of sessionStartEntries) {
261	      // clear and compact already exist — append the context hook alongside
262	      // the idle hook so both fire from the same matcher.
263	      entry.hooks.push(tagDash(contextHook));
264	    }
265	  }
266	
267	  dashEntries.SessionStart = sessionStartEntries;
268	
269	  try {
270	    if (!fs.existsSync(claudeDir)) {
271	      fs.mkdirSync(claudeDir, { recursive: true });
272	    }
273	
274	    let existing: Record<string, unknown> = {};
275	    if (fs.existsSync(settingsPath)) {
276	      try {
277	        const parsed = JSON.parse(fs.readFileSync(settingsPath, 'utf-8')) as unknown;
278	        // JSON.parse succeeds on "null", "42", "[]", etc. Only plain objects
279	        // can be spread and merged safely; anything else is treated as corrupt.
280	        if (parsed && typeof parsed === 'object' && !Array.isArray(parsed)) {
281	          existing = parsed as Record<string, unknown>;
282	        } else {
283	          throw new Error(`settings.local.json is not a JSON object (got ${typeof parsed})`);
284	        }
285	      } catch (err) {
286	        // Back up the corrupt file before overwriting so the user can recover.
287	        // If the backup rename fails, we MUST NOT proceed to overwrite — that
288	        // would destroy the user's on-disk file with no copy left.
289	        const backupPath = `${settingsPath}.corrupt-${Date.now()}.bak`;
290	        try {
291	          fs.renameSync(settingsPath, backupPath);
292	          console.error(
293	            `[writeHookSettings] settings.local.json corrupt at ${settingsPath}; backed up to ${backupPath}`,
294	            err,
295	          );
296	          broadcastToast(
297	            `settings.local.json was unreadable — backed up to ${path.basename(backupPath)} and rewritten.`,
298	          );
299	        } catch (renameErr) {
300	          console.error(
301	            '[writeHookSettings] Failed to back up corrupt file; leaving on-disk file intact:',
302	            renameErr,
303	          );
304	          broadcastToast(
305	            `settings.local.json is corrupt and could not be backed up — hooks are off for this task. Fix or remove ${path.basename(settingsPath)} manually.`,
306	          );
307	          return {
308	            ok: false,
309	            settingsPath,
310	            error: `corrupt settings.local.json; backup rename failed: ${renameErr instanceof Error ? renameErr.message : String(renameErr)}`,
311	          };
312	        }
313	      }
314	    }
315	
316	    const existingHooks =
317	      existing.hooks && typeof existing.hooks === 'object'
318	        ? (existing.hooks as Record<string, HookEntry[] | undefined>)
319	        : {};
320	
321	    const mergedHooks = mergeHookEntries(existingHooks, dashEntries);
322	
323	    const merged: Record<string, unknown> = {
324	      ...existing,
325	      hooks: mergedHooks,
326	    };
327	
328	    // The statusLine doubles as the context-usage reporter: it POSTs to the
329	    // context endpoint and discards output (so the bar stays blank). Same guarded
330	    // command shape as the hooks, so it too no-ops outside Dash.
331	    merged.statusLine = {
332	      type: 'command',
333	      command: hookCommand('context'),
334	    };
335	
336	    const effectiveAttribution =
337	      commitAttributionSetting === undefined ? DASH_DEFAULT_ATTRIBUTION : commitAttributionSetting;
338	    merged.attribution = { commit: effectiveAttribution };
339	
340	    // Pre-grant every project-level MCP server (.mcp.json) so Dash's first
341	    // spawn into a worktree doesn't trip "Allow this MCP server?" modals for
342	    // each one. The user already opted in by checking .mcp.json into the
343	    // project; making them re-approve per worktree is just friction. NOTE: a
344	    // narrower `enabledMcpjsonServers: [...]` allowlist is safer per Anthropic's
345	    // docs, but Dash can't know the server names without reading .mcp.json on
346	    // every settings write. Don't overwrite if user/team explicitly set either
347	    // key — let their decision win.
348	    if (
349	      typeof merged.enableAllProjectMcpServers !== 'boolean' &&
350	      !Array.isArray(merged.enabledMcpjsonServers)
351	    ) {
352	      merged.enableAllProjectMcpServers = true;
353	    }
354	
355	    atomicWriteFileSync(settingsPath, JSON.stringify(merged, null, 2) + '\n');
356	    writtenSettingsPaths.add(settingsPath);
357	    return { ok: true };
358	  } catch (err) {
359	    console.error('[writeHookSettings] Failed:', err);
360	    broadcastToast(`Could not write ${path.basename(settingsPath)} — hooks are off for this task.`);
361	    return {
362	      ok: false,
363	      settingsPath,
364	      error: err instanceof Error ? err.message : String(err),
365	    };
366	  }
367	}
