369	/**
370	 * Remove Dash-written hooks and attribution from all settings.local.json files
371	 * that were written during this session. Preserves user-authored entries
372	 * by filtering against the merge module's Dash-owned detector instead of
373	 * deleting the entire managed-event keys.
374	 */
375	export function cleanupHookSettings(): void {
376	  for (const settingsPath of writtenSettingsPaths) {
377	    try {
378	      if (!fs.existsSync(settingsPath)) continue;
379	
380	      const raw = JSON.parse(fs.readFileSync(settingsPath, 'utf-8'));
381	      const hooks = raw.hooks;
382	
383	      if (hooks && typeof hooks === 'object') {
384	        for (const key of DASH_HOOK_EVENTS) {
385	          const entries = hooks[key];
386	          if (!Array.isArray(entries)) continue;
387	          const userOnly = entries.filter((e) => !entryIsDashOwned(e));
388	          if (userOnly.length === 0) delete hooks[key];
389	          else hooks[key] = userOnly;
390	        }
391	        if (Object.keys(hooks).length === 0) {
392	          delete raw.hooks;
393	        }
394	      }
395	
396	      delete raw.statusLine;
397	      delete raw.attribution;
398	
399	      if (Object.keys(raw).length === 0) {
400	        fs.unlinkSync(settingsPath);
401	      } else {
402	        atomicWriteFileSync(settingsPath, JSON.stringify(raw, null, 2) + '\n');
403	      }
404	    } catch (err) {
405	      console.error(`[cleanupHookSettings] Failed for ${settingsPath}:`, err);
406	    }
407	  }
408	
409	  writtenSettingsPaths.clear();
410	}
